DO $$ BEGIN CREATE TYPE "StaffStatus" AS ENUM ('PENDING_SETUP','ACTIVE','DISABLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$; ALTER TABLE "StaffUser" ADD COLUMN IF NOT EXISTS "status" "StaffStatus" NOT NULL DEFAULT 'PENDING_SETUP'; ALTER TABLE "MfaCredential" ADD COLUMN IF NOT EXISTS "lastAcceptedStep" BIGINT NOT NULL DEFAULT -1; ALTER TABLE "StaffUser" ALTER COLUMN "status" SET DEFAULT 'PENDING_SETUP'; ALTER TABLE "Product" ADD CONSTRAINT "Product_price_nonnegative" CHECK ("priceMinor">=0); ALTER TABLE "Product" ADD CONSTRAINT "Product_cost_nonnegative" CHECK ("costMinor">=0); ALTER TABLE "SaleItem" ADD CONSTRAINT "SaleItem_quantity_positive" CHECK ("quantity">0); ALTER TABLE "PurchaseItem" ADD CONSTRAINT "PurchaseItem_quantity_positive" CHECK ("quantity">0); ALTER TABLE "Payment" ADD CONSTRAINT "Payment_amount_positive" CHECK ("amountMinor">0); ALTER TABLE "Refund" ADD CONSTRAINT "Refund_amount_positive" CHECK ("amountMinor">0); ALTER TABLE "Expense" ADD CONSTRAINT "Expense_amount_positive" CHECK ("amountMinor">0); ALTER TABLE "CustomerPayment" ADD CONSTRAINT "CustomerPayment_amount_positive" CHECK ("amountMinor">0); ALTER TABLE "SupplierPayment" ADD CONSTRAINT "SupplierPayment_amount_positive" CHECK ("amountMinor">0); CREATE UNIQUE INDEX IF NOT EXISTS "CashSession_one_open_per_cashier_terminal" ON "CashSession" ("openedById","terminalId") WHERE "status"='OPEN'; CREATE INDEX IF NOT EXISTS "AuditLog_entity_created_idx" ON "AuditLog" ("entity","entityId","createdAt");